@using sv_e36e652abc074744bd1ab042883299ff.Models

<h4>Personal Information</h4>

@if (!string.IsNullOrEmpty(ErrorMessage))
{
    <div class="alert alert-danger">@ErrorMessage</div>
}

<div class="mb-3">
    <label class="form-label">Full Name *</label>
    <input type="text" class="form-control" @bind="FullName" />
</div>

<div class="mb-3">
    <label class="form-label">Email *</label>
    <input type="email" class="form-control" @bind="Email" />
    @if (IsValidatingEmail)
    {
        <div class="form-text text-info">Validating email...</div>
    }
</div>

<div class="mb-3">
    <label class="form-label">Phone *</label>
    <input type="tel" class="form-control" @bind="Phone" />
</div>

<div class="mb-3">
    <label class="form-label">Address *</label>
    <textarea class="form-control" rows="2" @bind="Address"></textarea>
</div>

<div class="d-flex justify-content-end">
    <button class="btn btn-primary" @onclick="HandleNext" disabled="@IsValidatingEmail">Next</button>
</div>

@code {
    [Parameter] public string FullName { get; set; } = "";
    [Parameter] public string Email { get; set; } = "";
    [Parameter] public string Phone { get; set; } = "";
    [Parameter] public string Address { get; set; } = "";
    [Parameter] public EventCallback<PersonalInfo> OnNext { get; set; }
    [Parameter] public IApplicationService ApplicationService { get; set; } = default!;

    private string? ErrorMessage;
    private bool IsValidatingEmail;

    private async Task HandleNext()
    {
        ErrorMessage = null;

        if (string.IsNullOrWhiteSpace(FullName))
        {
            ErrorMessage = "Full name is required.";
            return;
        }
        if (string.IsNullOrWhiteSpace(Email))
        {
            ErrorMessage = "Email is required.";
            return;
        }
        if (string.IsNullOrWhiteSpace(Phone))
        {
            ErrorMessage = "Phone is required.";
            return;
        }
        if (string.IsNullOrWhiteSpace(Address))
        {
            ErrorMessage = "Address is required.";
            return;
        }

        IsValidatingEmail = true;
        StateHasChanged();

        var isValid = await ApplicationService.ValidateEmailAsync(Email);
        IsValidatingEmail = false;

        if (!isValid)
        {
            ErrorMessage = "Please enter a valid email address.";
            return;
        }

        await OnNext.InvokeAsync(new PersonalInfo(FullName.Trim(), Email.Trim(), Phone.Trim(), Address.Trim()));
    }
}

@using sv_e36e652abc074744bd1ab042883299ff.Models

<h4>Work History</h4>

@if (!string.IsNullOrEmpty(ErrorMessage))
{
    <div class="alert alert-danger">@ErrorMessage</div>
}

@for (int i = 0; i < Entries.Count; i++)
{
    var idx = i;
    var entry = Entries[idx];
    <WorkEntryForm Index="idx"
                   Company="@entry.Company"
                   Title="@entry.Title"
                   StartDate="@entry.StartDate"
                   EndDate="@entry.EndDate"
                   IsCurrent="@entry.IsCurrent"
                   Description="@entry.Description"
                   CanRemove="@(Entries.Count > 1)"
                   OnRemove="() => RemoveEntry(idx)"
                   OnChanged="data => UpdateEntry(data)" />
}

<button type="button" class="btn btn-outline-secondary mb-3" @onclick="AddEntry">
    + Add Another Position
</button>

<div class="d-flex justify-content-between">
    <button class="btn btn-secondary" @onclick="HandleBack">Back</button>
    <button class="btn btn-primary" @onclick="HandleNext">Next</button>
</div>

@code {
    [Parameter] public List<EntryModel> Entries { get; set; } = new();
    [Parameter] public EventCallback OnBack { get; set; }
    [Parameter] public EventCallback<List<EntryModel>> OnNext { get; set; }

    private string? ErrorMessage;

    public class EntryModel
    {
        public string Company { get; set; } = "";
        public string Title { get; set; } = "";
        public DateTime StartDate { get; set; } = DateTime.Today;
        public DateTime? EndDate { get; set; }
        public bool IsCurrent { get; set; }
        public string Description { get; set; } = "";
    }

    protected override void OnInitialized()
    {
        if (Entries.Count == 0)
        {
            Entries.Add(new EntryModel());
        }
    }

    private void AddEntry()
    {
        Entries.Add(new EntryModel());
    }

    private void RemoveEntry(int index)
    {
        if (Entries.Count > 1)
        {
            Entries.RemoveAt(index);
        }
    }

    private void UpdateEntry(WorkEntryForm.WorkEntryData data)
    {
        if (data.Index < Entries.Count)
        {
            var entry = Entries[data.Index];
            entry.Company = data.Company;
            entry.Title = data.Title;
            entry.StartDate = data.StartDate;
            entry.EndDate = data.EndDate;
            entry.IsCurrent = data.IsCurrent;
            entry.Description = data.Description;
        }
    }

    private async Task HandleBack()
    {
        await OnBack.InvokeAsync();
    }

    private async Task HandleNext()
    {
        ErrorMessage = null;

        foreach (var entry in Entries)
        {
            if (string.IsNullOrWhiteSpace(entry.Company) || string.IsNullOrWhiteSpace(entry.Title))
            {
                ErrorMessage = "Each position must have a company name and job title.";
                return;
            }
        }

        await OnNext.InvokeAsync(Entries);
    }
}

