@using sv_e36e652abc074744bd1ab042883299ff.Models

<h4>Personal Information</h4>

@if (!string.IsNullOrEmpty(ErrorMessage))
{
    <div class="alert alert-danger">@ErrorMessage</div>
}

<div class="mb-3">
    <label class="form-label">Full Name *</label>
    <input type="text" class="form-control" @bind="FullName" />
</div>

<div class="mb-3">
    <label class="form-label">Email *</label>
    <input type="email" class="form-control" @bind="Email" />
    @if (IsValidatingEmail)
    {
        <div class="form-text text-info">Validating email...</div>
    }
</div>

<div class="mb-3">
    <label class="form-label">Phone *</label>
    <input type="tel" class="form-control" @bind="Phone" />
</div>

<div class="mb-3">
    <label class="form-label">Address *</label>
    <textarea class="form-control" rows="2" @bind="Address"></textarea>
</div>

<div class="d-flex justify-content-end">
    <button class="btn btn-primary" @onclick="HandleNext" disabled="@IsValidatingEmail">Next</button>
</div>

@code {
    [Parameter] public string FullName { get; set; } = "";
    [Parameter] public string Email { get; set; } = "";
    [Parameter] public string Phone { get; set; } = "";
    [Parameter] public string Address { get; set; } = "";
    [Parameter] public EventCallback<PersonalInfo> OnNext { get; set; }
    [Parameter] public IApplicationService ApplicationService { get; set; } = default!;

    private string? ErrorMessage;
    private bool IsValidatingEmail;

    private async Task HandleNext()
    {
        ErrorMessage = null;

        if (string.IsNullOrWhiteSpace(FullName))
        {
            ErrorMessage = "Full name is required.";
            return;
        }
        if (string.IsNullOrWhiteSpace(Email))
        {
            ErrorMessage = "Email is required.";
            return;
        }
        if (string.IsNullOrWhiteSpace(Phone))
        {
            ErrorMessage = "Phone is required.";
            return;
        }
        if (string.IsNullOrWhiteSpace(Address))
        {
            ErrorMessage = "Address is required.";
            return;
        }

        IsValidatingEmail = true;
        StateHasChanged();

        var isValid = await ApplicationService.ValidateEmailAsync(Email);
        IsValidatingEmail = false;

        if (!isValid)
        {
            ErrorMessage = "Please enter a valid email address.";
            return;
        }

        await OnNext.InvokeAsync(new PersonalInfo(FullName.Trim(), Email.Trim(), Phone.Trim(), Address.Trim()));
    }
}

