arguments.file_text:
@using sv_e36e652abc074744bd1ab042883299ff.Models

<h4>Review &amp; Submit</h4>

@if (IsSubmitting)
{
    <div class="text-center my-4">
        <div class="spinner-border text-primary" role="status"></div>
        <p class="mt-2">Submitting your application...</p>
    </div>
}
else if (SubmittedId.HasValue)
{
    <div class="alert alert-success text-center">
        <h5>&#10003; Application Submitted Successfully!</h5>
        <p>Your application ID is: <strong>@SubmittedId.Value</strong></p>
    </div>
}
else
{
    @if (!string.IsNullOrEmpty(ErrorMessage))
    {
        <div class="alert alert-danger">@ErrorMessage</div>
    }

    <div class="review-section">
        <div class="section-header">
            <h5>Personal Information</h5>
            <button class="btn btn-link btn-sm" @onclick="() => OnEditStep.InvokeAsync(0)">Edit</button>
        </div>
        <dl class="row">
            <dt class="col-sm-3">Name</dt><dd class="col-sm-9">@Personal.FullName</dd>
            <dt class="col-sm-3">Email</dt><dd class="col-sm-9">@Personal.Email</dd>
            <dt class="col-sm-3">Phone</dt><dd class="col-sm-9">@Personal.Phone</dd>
            <dt class="col-sm-3">Address</dt><dd class="col-sm-9">@Personal.Address</dd>
        </dl>
    </div>

    <div class="review-section">
        <div class="section-header">
            <h5>Work History</h5>
            <button class="btn btn-link btn-sm" @onclick="() => OnEditStep.InvokeAsync(1)">Edit</button>
        </div>
        @foreach (var entry in WorkEntries)
        {
            <div class="mb-2 ps-2 border-start border-3">
                <strong>@entry.Title</strong> at @entry.Company<br />
                <small class="text-muted">
                    @entry.StartDate.ToString("MMM yyyy") &ndash;
                    @(entry.EndDate.HasValue ? entry.EndDate.Value.ToString("MMM yyyy") : "Present")
                </small>
                @if (!string.IsNullOrWhiteSpace(entry.Description))
                {
                    <p class="mb-0 mt-1">@entry.Description</p>
                }
            </div>
        }
    </div>

    <div class="review-section">
        <div class="section-header">
            <h5>References</h5>
            <button class="btn btn-link btn-sm" @onclick="() => OnEditStep.InvokeAsync(2)">Edit</button>
        </div>
        @foreach (var r in References)
        {
            <div class="mb-2">
                <strong>@r.Name</strong> (@r.Relationship)<br />
                <small>@r.Email &bull; @r.Phone</small>
            </div>
        }
    </div>

    <div class="review-section">
        <div class="section-header">
            <h5>Cover Letter</h5>
            <button class="btn btn-link btn-sm" @onclick="() => OnEditStep.InvokeAsync(3)">Edit</button>
        </div>
        <p class="cover-letter-preview">@CoverLetter</p>
    </div>

    <div class="d-flex justify-content-between mt-4">
        <button class="btn btn-secondary" @onclick="HandleBack">Back</button>
        <button class="btn btn-success btn-lg" @onclick="HandleSubmit">Submit Application</button>
    </div>
}

@code {
    [Parameter] public PersonalInfo Personal { get; set; } = default!;
    [Parameter] public List<WorkEntry> WorkEntries { get; set; } = new();
    [Parameter] public List<Reference> References { get; set; } = new();
    [Parameter] public string CoverLetter { get; set; } = "";
    [Parameter] public EventCallback OnBack { get; set; }
    [Parameter] public EventCallback<int> OnEditStep { get; set; }
    [Parameter] public EventCallback OnSubmit { get; set; }

    [Parameter] public bool IsSubmitting { get; set; }
    [Parameter] public int? SubmittedId { get; set; }
    [Parameter] public string? ErrorMessage { get; set; }

    private async Task HandleBack()
    {
        await OnBack.InvokeAsync();
    }

    private async Task HandleSubmit()
    {
        await OnSubmit.InvokeAsync();
    }
}

