arguments.file_text:
@page "/apply"
@using sv_e36e652abc074744bd1ab042883299ff.Models
@inject IApplicationService ApplicationService
@rendermode InteractiveServer

<PageTitle>Job Application</PageTitle>

<div class="container py-4" style="max-width: 800px;">
    <h2 class="text-center mb-4">Job Application</h2>

    <StepIndicator CurrentStep="@currentStep" OnStepSelected="GoToStep" />

    @switch (currentStep)
    {
        case 0:
            <PersonalInfoStep FullName="@personalFullName"
                              Email="@personalEmail"
                              Phone="@personalPhone"
                              Address="@personalAddress"
                              ApplicationService="@ApplicationService"
                              OnNext="HandlePersonalNext" />
            break;

        case 1:
            <WorkHistoryStep Entries="@workEntries"
                             OnBack="() => currentStep--"
                             OnNext="HandleWorkNext" />
            break;

        case 2:
            <ReferencesStep References="@references"
                            OnBack="() => currentStep--"
                            OnNext="HandleReferencesNext" />
            break;

        case 3:
            <CoverLetterStep CoverLetterText="@coverLetter"
                             OnBack="() => currentStep--"
                             OnNext="HandleCoverLetterNext" />
            break;

        case 4:
            <ReviewStep Personal="@GetPersonalInfo()"
                        WorkEntries="@GetWorkEntries()"
                        References="@GetReferences()"
                        CoverLetter="@coverLetter"
                        IsSubmitting="@isSubmitting"
                        SubmittedId="@submittedId"
                        ErrorMessage="@submitError"
                        OnBack="() => currentStep--"
                        OnEditStep="GoToStep"
                        OnSubmit="HandleSubmit" />
            break;
    }
</div>

@code {
    private int currentStep;

    // Step 1 state
    private string personalFullName = "";
    private string personalEmail = "";
    private string personalPhone = "";
    private string personalAddress = "";

    // Step 2 state
    private List<WorkHistoryStep.EntryModel> workEntries = new();

    // Step 3 state
    private List<ReferencesStep.ReferenceModel> references = new();

    // Step 4 state
    private string coverLetter = "";

    // Step 5 state
    private bool isSubmitting;
    private int? submittedId;
    private string? submitError;

    private void GoToStep(int step)
    {
        if (step < currentStep)
        {
            currentStep = step;
        }
    }

    private void HandlePersonalNext(PersonalInfo info)
    {
        personalFullName = info.FullName;
        personalEmail = info.Email;
        personalPhone = info.Phone;
        personalAddress = info.Address;
        currentStep = 1;
    }

    private void HandleWorkNext(List<WorkHistoryStep.EntryModel> entries)
    {
        workEntries = entries;
        currentStep = 2;
    }

    private void HandleReferencesNext(List<ReferencesStep.ReferenceModel> refs)
    {
        references = refs;
        currentStep = 3;
    }

    private void HandleCoverLetterNext(string text)
    {
        coverLetter = text;
        currentStep = 4;
    }

    private async Task HandleSubmit()
    {
        isSubmitting = true;
        submitError = null;
        StateHasChanged();

        try
        {
            var application = new JobApplication(
                GetPersonalInfo(),
                new WorkHistory(GetWorkEntries()),
                GetReferences(),
                coverLetter
            );

            submittedId = await ApplicationService.SubmitApplicationAsync(application);
        }
        catch (Exception ex)
        {
            submitError = $"Submission failed: {ex.Message}";
        }
        finally
        {
            isSubmitting = false;
        }
    }

    private PersonalInfo GetPersonalInfo() =>
        new(personalFullName, personalEmail, personalPhone, personalAddress);

    private List<WorkEntry> GetWorkEntries() =>
        workEntries.Select(e => new WorkEntry(
            e.Company, e.Title, e.StartDate, e.IsCurrent ? null : e.EndDate, e.Description
        )).ToList();

    private List<Reference> GetReferences() =>
        references.Select(r => new Reference(r.Name, r.Relationship, r.Email, r.Phone)).ToList();
}

