    <div class="entry-header">
        <h5>Position @(Index + 1)</h5>
        @if (CanRemove)
        {
            <button type="button" class="btn btn-outline-danger btn-sm" @onclick="OnRemove">Remove</button>
        }
    </div>

    <div class="row mb-3">
        <div class="col-md-6">
