            <label class="form-label">Job Title *</label>
            <input type="text" class="form-control" @bind="Title" @bind:after="NotifyChanged" />
        </div>
    </div>

    <div class="row mb-3">
        <div class="col-md-4">
            <label class="form-label">Start Date *</label>
            <input type="date" class="form-control" @bind="StartDate" @bind:after="NotifyChanged" />
        </div>
        <div class="col-md-4">
            <label class="form-label">End Date</label>
            <input type="date" class="form-control" @bind="EndDate" @bind:after="NotifyChanged"
                   disabled="@IsCurrent" />
        </div>
        <div class="col-md-4 d-flex align-items-end">
            <div class="form-check mb-2">
                <input type="checkbox" class="form-check-input" id="@CurrentCheckId"
                       @bind="IsCurrent" @bind:after="HandleCurrentChanged" />
                <label class="form-check-label" for="@CurrentCheckId">Currently working here</label>
            </div>
        </div>
    </div>

    <div class="mb-3">
        <label class="form-label">Description</label>
        <textarea class="form-control" rows="3" @bind="Description" @bind:after="NotifyChanged"></textarea>
    </div>
</div>

@code {
    [Parameter] public int Index { get; set; }
    [Parameter] public string Company { get; set; } = "";
    [Parameter] public string Title { get; set; } = "";
    [Parameter] public DateTime StartDate { get; set; } = DateTime.Today;
    [Parameter] public DateTime? EndDate { get; set; }
    [Parameter] public bool IsCurrent { get; set; }
    [Parameter] public string Description { get; set; } = "";
    [Parameter] public bool CanRemove { get; set; }
    [Parameter] public EventCallback OnRemove { get; set; }
    [Parameter] public EventCallback<WorkEntryData> OnChanged { get; set; }

    private string CurrentCheckId => $"current-{Index}";

    public class WorkEntryData
    {
        public int Index { get; set; }
        public string Company { get; set; } = "";
        public string Title { get; set; } = "";
        public DateTime StartDate { get; set; }
        public DateTime? EndDate { get; set; }
        public bool IsCurrent { get; set; }
        public string Description { get; set; } = "";
    }

    private void HandleCurrentChanged()
    {
        if (IsCurrent) EndDate = null;
        NotifyChanged();
    }

    private void NotifyChanged()
    {
        OnChanged.InvokeAsync(new WorkEntryData
        {
            Index = Index,
            Company = Company,
            Title = Title,
            StartDate = StartDate,
            EndDate = IsCurrent ? null : EndDate,
            IsCurrent = IsCurrent,
            Description = Description
        });
    }
}

